'use strict';
const Sidae={
 profile:null,
 load(){try{const p=JSON.parse(localStorage.getItem('sidae.profile.v1'));if(p&&p.version===1&&SidaeCore.questions.every(q=>[0,1].includes(p.answers[q.id])))this.profile=p;}catch{}},
 shell(title,body,kicker='時代因材 · 시대와 환경에 따라 달라지는 나'){app.innerHTML=`<section class="sd-page"><p class="sd-kicker">${kicker}</p><h1>${title}</h1>${body}</section>`;window.scrollTo(0,0);},
 home(){app.innerHTML=`<section class="ku-hero" aria-labelledby="ku-title"><div class="ku-cover"><img src="assets/kuong/cover.png" width="1672" height="941" fetchpriority="high" alt="시대인재. 과잠 입은 현재의 쿠옹이를 중심으로 장인, 학자, 상인, 역관, 화원 쿠옹이가 펼쳐진 역사 속 풍경"></div><div class="ku-hero-bar"><div><p class="sd-kicker">時代因材 · 역사 속 또 다른 나</p><h1 id="ku-title">시대인재<span>사주로 보는 나의 역사적 직업</span></h1><p>생년월일과 가치관으로 발견하는 역사 속 또 다른 나</p></div><div class="ku-start"><button class="primary" data-sd="form">나의 역사적 직업 알아보기 <span>→</span></button><div class="ku-secondary"><button class="secondary" data-action="setup">「마지막 도구」 바로 체험</button>${saved?'<button class="secondary" data-action="resume">이어 읽기 →</button>':''}</div><small>입력·탐색 약 3분 · 이야기는 내 속도로</small></div></div></section><section class="ku-invitation"><p>당신이 다른 시대에 태어났다면, 어떤 삶을 살았을까?</p><span>쿠옹이와 가능성을 발견하고, 당신의 선택으로 이야기를 이어가세요.</span></section><section class="sd-steps"><article><b>01 / 발견</b><h2>나는 무엇을 중시할까</h2><p>직접 고른 가치관과 전통의 상징으로 출발합니다.</p></article><article><b>02 / 체험</b><h2>그 시대에서도 같을까</h2><p>한 장인의 삶, 세 번의 선택, 여덟 갈래의 여운.</p></article><article><b>03 / 돌아보기</b><h2>선택이 남긴 또 다른 나</h2><p>처음의 생각과 이야기 속 행동을 나란히 봅니다.</p></article></section><section class="sd-intent"><p class="sd-kicker">人才에서 因材로</p><h2>가능성은 시대를 만날 때<br>다른 모습으로 피어납니다.</h2><p>역사를 암기하는 대신, 직접 살아보는 새로운 체험.<br>명리학은 전통적인 상징 체계입니다. 성격 진단이나 미래 예측을 제공하지 않습니다.</p><button class="secondary" data-sd="method">계산과 추천의 기준</button></section>`;},
 form(){state.view='discover';this.shell('당신의 출발점을 알려주세요.',`${Kuong.guide("curious","어떤 모습의 나를 만나게 될까요?","지금의 나에게 가까운 답을 골라주세요. 출생 정보는 계산에만 사용하고 이름은 묻지 않아요.")}<form id="sd-form"><div class="sd-panel"><h2>01 · 태어난 날과 시각</h2><p>1900년부터 현재까지 출생일을 입력할 수 있어요. 한국 표준시(UTC+9) 기준으로 계산하며, 해외 출생·과거 표준시·서머타임·진태양시 보정은 지원하지 않습니다.</p><div class="sd-fields"><label>달력<select name="calendar"><option value="solar">양력</option><option value="lunar">음력</option></select></label><label class="sd-check"><input name="leap" type="checkbox" disabled> 음력 윤달</label><label>출생 연도<input type="number" name="year" min="${SidaeCore.birthYears.min}" max="${SidaeCore.birthYears.max}" placeholder="1992" required></label><label>월<input type="number" name="month" min="1" max="12" required></label><label>일<input type="number" name="day" min="1" max="31" required></label><label>출생 시각<input type="time" name="time" value="12:00" required></label><label class="sd-check"><input type="checkbox" name="unknown"> 출생 시각을 모릅니다</label></div><details><summary>날짜 경계 기준</summary><label>일주가 바뀌는 시각<select name="boundary"><option value="midnight">자정(00:00) · 기본</option><option value="jasi">자시 시작(23:00)</option><option value="splitJasi">야자시 구분 · 일주 00:00, 시주 23:00</option></select></label><p>년주는 입춘, 월주는 절입 시각을 기준으로 합니다. 학파에 따라 날짜·시각 보정 기준이 다를 수 있습니다.</p></details></div><div class="sd-panel"><h2>02 · 지금의 당신이 고르는 것</h2><p>정답은 없습니다. 더 가까운 쪽을 골라주세요.</p>${SidaeCore.questions.map((q,n)=>`<fieldset><legend>${n+1}. ${q.title}</legend><div class="sd-options">${q.options.map((o,i)=>`<label><input type="radio" name="${q.id}" value="${i}" required><span>${o}</span></label>`).join('')}</div></fieldset>`).join('')}</div><label class="sd-check"><input type="checkbox" name="remember"> 가치관 답변과 분석 결과를 이 브라우저에 보관합니다. (생년월일·출생 시각 제외)</label><p class="sd-fine">선택하지 않으면 분석은 새로고침할 때 사라집니다. 게임을 시작하면 그 회차의 가치관 답변은 선택 기록과 함께 기기에 저장됩니다.</p><div id="ku-loading" class="ku-loading" role="status" aria-live="polite" hidden>${Kuong.guide("excited","역사 속 가능성을 찾고 있어요","입력한 정보를 계산하고, 가치관에 맞는 활동을 비교하고 있어요.")}</div><p id="sd-error" role="alert"></p><button class="primary" type="submit">나의 또 다른 가능성 보기 →</button><button type="button" class="secondary" data-action="home">돌아가기</button></form>`);},
 async submit(form){const submitButton=form.querySelector('button[type="submit"]'),loading=document.getElementById('ku-loading');submitButton.disabled=true;form.setAttribute('aria-busy','true');loading.hidden=false;await Kuong.paint();if(document.getElementById('sd-form')!==form)return;const f=new FormData(form),answers=Object.fromEntries(SidaeCore.questions.map(q=>[q.id,Number(f.get(q.id))]));const [hour,minute]=String(f.get('time')||'12:00').split(':').map(Number);try{const chart=SidaeCore.calculate({year:+f.get('year'),month:+f.get('month'),day:+f.get('day'),lunar:f.get('calendar')==='lunar',leap:f.has('leap'),unknown:f.has('unknown'),hour,minute,boundary:f.get('boundary')},Manseryeok);this.profile={version:1,answers,chart:{pillars:chart.pillars,elements:chart.elements,sorted:chart.sorted,unknown:chart.unknown,boundary:chart.boundary,ambiguous:chart.ambiguous,dayElement:chart.dayElement}};try{if(f.has('remember'))localStorage.setItem('sidae.profile.v1',JSON.stringify(this.profile));else localStorage.removeItem('sidae.profile.v1');}catch{toast('기기 저장은 사용할 수 없습니다. 현재 화면에서만 이어갑니다.');}this.analysis();}catch(e){document.getElementById('sd-error').textContent=e.message;loading.hidden=true;submitButton.disabled=false;form.removeAttribute('aria-busy');}},
 analysis(){if(!this.profile){this.form();return;}state.view='analysis';const {chart:c,answers:a}=this.profile,top=c.sorted.filter(e=>c.elements[e]>0).slice(0,3),total=Object.values(c.elements).reduce((a,b)=>a+b,0);const rec=SidaeCore.recommend(a,c);this.shell('당신에게 열리는 세 가지 가능성',`${Kuong.guide("neutral","쿠옹이와 나의 가능성을 읽어봐요","전통의 상징은 작은 실마리. 더 큰 출발점은 당신이 직접 고른 가치관이에요.")}<div class="sd-panel"><p class="sd-kicker">QUICK · 상징으로 읽는 성향</p><h2>나의 핵심 성향 3가지</h2>${Kuong.traits(c,a)}<p>확정된 기둥의 오행 개수로 고른 세 가지 키워드입니다. 동률은 목·화·토·금·수 순으로 표시하며, 분포에 없는 오행은 키워드에 포함하지 않습니다. 실제 성격을 판정한 결과는 아닙니다.</p><div class="sd-two"><div><h3 class="ku-section-title">${Kuong.sprite("sparkle")}<span>강점으로 떠올려볼 것</span></h3><ul>${top.map(e=>`<li>${SidaeCore.symbolism[e].strength}</li>`).join('')}</ul></div><div><h3 class="ku-section-title">${Kuong.sprite("resolve")}<span>주의하며 돌아볼 성향</span></h3><ul>${top.slice(0,2).map(e=>`<li>${SidaeCore.symbolism[e].care}</li>`).join('')}</ul></div></div><div class="ku-environment">${Kuong.sprite("wink")}<p><b>선호할 수 있는 환경</b><br>${SidaeCore.symbolism[top[0]].environment}</p></div><details><summary>실제 계산값 · 오행과 십신 보기</summary><p>${c.unknown?'시각 미상: 하루 1,440분을 계산해 일치하는 기둥만 확정합니다. 시주는 산출하지 않습니다.':'한국 표준시(UTC+9) · 경도/진태양시 보정 없음'} / 날짜 경계: ${esc(c.boundary)}</p>${c.ambiguous?'<p class="notice">절기 또는 날짜 경계를 포함해 기둥이 달라집니다. 아래 후보를 하나의 확정값으로 해석하지 마세요. 오행에는 확정 기둥만 집계합니다.</p>':''}<div class="sd-pillars">${['year','month','day','hour'].map((k,i)=>{const p=c.pillars[k];return `<article><small>${['년주','월주','일주','시주'][i]}</small><strong>${p.unknown?'미산출':esc(p.candidates.join(' / '))}</strong><span>${esc(p.hanja||'')}</span><p>${p.stem?'천간 '+p.stem+' · 지지 '+p.branch:''}</p><small>${p.ten?'천간 '+p.ten.stem+' / 지지 본기 '+p.ten.branch:'십신 확정 불가'}</small></article>`;}).join('')}</div>${Object.entries(c.elements).map(([e,n])=>`<div class="sd-bar"><b>${e}</b><meter min="0" max="${total||1}" value="${n}" aria-label="${e} ${n}개"></meter><span>${n}개</span></div>`).join('')}<p>천간·지지의 대표 오행을 같은 비중으로 센 단순 분포입니다. 지장간 전체나 월령 가중치, 강약·격국·용신·조후 판정을 한 값이 아닙니다. 십신은 일간 기준이며 지지는 본기를 사용합니다.</p><button class="secondary" data-sd="method">자료와 계산 범위 보기</button></details></div><h2>역사 속 또 다른 나 · TOP 3</h2><p>추천 순위는 탐색을 위한 편집 규칙입니다. 쿠옹이의 복장은 활동 분야를 안내하는 상징이며, 실제 인물의 초상이나 정확한 직업 복식을 재현한 것은 아닙니다.</p><div class="sd-recs">${rec.map((r,i)=>`<article class="sd-rec"><span class="sd-rank">0${i+1}</span>${Kuong.recommendation(r,i)}<p class="sd-kicker">${r.era}</p><h2>${r.job}</h2><p class="sd-person">${r.person}</p><p><b>가장 가까웠던 답변</b><br>${r.reasons.map(x=>esc(x)).join(" · ")}</p><p><b>가치관 연결</b> · ${a.community?'함께 남기는 성과':'내 이름으로 남기는 완성'}와 ${a.risk?'도전':'안정'}을 기준으로 활동 환경을 비교했습니다.</p><p><b>활동 연결</b> · ${a.activity?'연구와 탐구':'제작과 수리'}, ${a.interest?'관찰과 기록':'사람과 교류'} 선호를 반영했습니다.</p><p><b>상징 연결</b> · ${r.e}의 ‘${SidaeCore.symbolism[r.e].word}’를 이 활동의 비유로 연결했습니다.</p><details><summary>왜 이 추천인가 · 역사적 근거</summary><p>${r.fact}</p><p>${r.context}</p><p>추천 구성 점수: 가치관 ${Math.round(r.parts.values*100)} / 활동 ${Math.round(r.parts.interests*100)} / 상징 ${Math.round(r.parts.symbolic*100)}. 적성 확률이 아닙니다.</p><a href="${r.source}" target="_blank" rel="noopener">한국민족문화대백과사전 ↗</a></details><span class="sd-status">${r.play?'현재 체험 가능 · 창작 속 장인의 삶':'역사 소개 제공 · 체험 게임 없음'}</span></article>`).join('')}</div><div class="sd-panel sd-bridge"><div class="ku-bridge-character">${Kuong.sprite("artisan","ku-job")}</div><p class="sd-kicker">지금 체험할 수 있는 이야기</p><h2>가능성을 만났다면,<br>이제 한 삶을 살아볼까요?</h2><p>쿠옹이가 안내하는 대표 체험 · 1792년 조선의 장인</p><p>${this.intro(a)}</p><p>추천 순위와 관계없이 「마지막 도구」에서 장인의 삶을 체험할 수 있습니다. 분석은 선택지나 엔딩을 결정하지 않습니다.</p><button class="primary" data-action="setup">「마지막 도구」로 들어가기 →</button><button class="secondary" data-sd="form">다시 입력</button></div>`);},
 intro(a){return a?`당신은 ${a.community?'여럿이 함께 이어가는 성과':'내 이름으로 완성한 한 작품'}를 더 중요하게 골랐습니다. 하지만 납기가 다가오는 조선의 작업장에서도 같은 선택을 하게 될까요?`:'어떤 삶을 살지는 아직 정해지지 않았습니다. 세 번의 선택으로 당신의 답을 남겨보세요.';},
 setup(){gameSetup();const notice=app.querySelector('.notice');if(notice)notice.innerHTML=Kuong.guide('resolve','선택은 이제 당신의 몫이에요',esc(this.intro(this.profile?.answers)));},
 begin(){state.sidae={version:1,answers:this.profile?.answers||null,choices:[],startedAt:new Date().toISOString()};},
 record(path){if(!state.sidae)state.sidae={version:1,answers:null,choices:[],startedAt:null};state.sidae.choices=SidaeCore.record(state.sidae.choices,path,choiceAt(path.length-1,path).title);},
 result(){const p=state.path,o=story.outcomes[p];if(!o){go('home');return;}const title=SidaeCore.endings[p][0],run=state.sidae||{},cmp=SidaeCore.compare(run.answers,p);if(run.version){run.ending=p;run.finishedAt=run.finishedAt||new Date().toISOString();}this.shell('나의 또 다른 삶',`${Kuong.guide(Kuong.ending(p),'이번 삶에서 발견한 나','선택에는 각자의 이유가 있었어요. 처음의 마음과 이야기 속 행동을 천천히 나란히 살펴봐요.')}<div class="sd-life" style="--ending:${SidaeCore.endings[p][1]}"><p>時代因材 · 조선 · 각자장</p><div class="sd-card-art" data-ending="${p}"><i class="sd-card-master"></i><i class="sd-card-yun"></i><span>${['刻','傳','準','共','影','手','立','續'][Object.keys(SidaeCore.endings).indexOf(p)]}</span></div><h2>${title}</h2><p>${esc(this.clean(o.tool))}</p></div><div class="actions"><button class="primary" data-sd="card">결과 이미지 저장 ↓</button><button class="secondary" data-sd="share">결과 공유 ↗</button><button class="secondary" data-action="reread">결말 다시 읽기</button></div><div class="sd-panel"><h2>내가 내린 세 번의 선택</h2>${p.split('').map((_,i)=>{const path=p.slice(0,i+1),r=run.choices?.find(x=>x.path===path);return `<article class="sd-choice"><small>선택 ${i+1} · ${r?esc(new Date(r.at).toLocaleString('ko-KR')):'이전 저장 기록 · 시각 정보 없음'}</small><h3>${esc(choiceAt(i,p).title)}</h3><p>${esc(choiceAt(i,p).text)}</p><p><b>이야기에 남긴 변화</b> · ${esc(SidaeCore.choiceImpacts[path])}</p><div class="sd-tags">${SidaeCore.choiceValues[path].map(x=>`<span>${x}</span>`).join('')}</div></article>`;}).join('')}</div><div class="sd-panel"><h2>지금의 나와, 이야기 속 나</h2>${run.answers?`<h3>이어진 가치관</h3>${cmp.same.length?cmp.same.map(t=>`<p>‘${t.label}’라는 답과 연결됩니다. ${t.text}</p>`).join(''):'<p>이번 두 비교 항목에서는 같은 방향의 선택이 확인되지 않았습니다.</p>'}<h3>달라진 선택</h3>${cmp.different.length?cmp.different.map(t=>`<p>처음에는 ‘${t.label}’를 골랐습니다. 그런데 ${t.text}</p>`).join(''):'<p>이번 두 비교 항목에서는 처음 답한 방향을 이어갔습니다.</p>'}`:'<p>이 회차에는 사전 가치관 답변이 없습니다. 입력하지 않은 가치관을 추측해 비교하지 않습니다.</p>'}<p>시대와 환경이 달라지면 같은 사람도 다른 선택을 할 수 있습니다. 이는 게임 속 행동에 대한 해석이며, 실제 성격을 판정한 결과가 아닙니다.</p></div><div class="sd-panel"><h2>이야기 바깥의 역사</h2><p>1792년 조선에서는 황양목으로 생생자를 제작했습니다. 하지만 이 작품의 주인공과 윤서, 세 번의 선택, 개인의 후일담은 창작입니다.</p><a href="https://encykorea.aks.ac.kr/Article/E0027516" target="_blank" rel="noopener">생생자의 실제 역사 읽기 ↗</a><p>이 결과의 직업은 플레이한 이야기의 ‘각자장’입니다. 추천받은 역사 인물의 실제 생애를 재현한 것은 아닙니다.</p></div><div class="actions"><button class="primary" data-action="replay">다른 선택으로 다시 살기 →</button><button class="secondary" data-action="home">시대인재 처음으로</button></div>`,'선택의 끝에서 · 조선의 장인으로 살다');},
 clean(s){return s.replace(/^\[[^\]]*\]\s*/,'').replace(/\b[123][AB]\b/g,'').replace(/→/g,'; ').replace(/머뭅니다가/g,'머물다가');},
 method(){openModal(`<h2>계산과 추천의 기준</h2><p>계산: manseryeok 2.0.0, MIT 라이선스. 고정한 소스의 계산 엔진을 브라우저에서 실행합니다. AI가 간지를 생성하지 않습니다.</p><p>이 화면의 입력 지원 범위: 1900~${SidaeCore.birthYears.max}년, UTC+9. 역사적 서머타임, 해외 현지시각, 진태양시 보정은 미지원입니다. 년주·월주는 입춘·절입, 일주는 선택한 날짜 경계를 적용합니다. 절입 계산은 분 단위 자료를 사용하므로 경계의 초 단위 확정은 지원하지 않습니다.</p><p>엔진에 포함된 한국 음양력 변환 자료를 사용합니다. KASI OpenAPI 응답 구조는 확인했지만 인증키가 없어 실시간 API 대조는 하지 않았습니다. 음력 월건을 절기 기준 사주 월주와 동일시하지 않습니다.</p><p>추천 가중치: 가치관 40%, 활동·관심사 30%, 명리 상징 30%. 수정 가능한 초기 설계값이며 검증된 적성 비율이 아닙니다. 역사 인물의 성격은 추정하지 않고, 활동과 환경에 편집상 연결값을 부여했습니다. 같은 직업군이 중복되지 않게 고릅니다.</p><p>QUICK 해석은 오행의 일반적인 상징을 활용한 규칙 기반 안내입니다. AI 상담, 격국·용신·신강약·조후의 전문 판정, 대운·세운·신살은 제공하지 않습니다. 《자평진전》《적천수》《궁통보감》의 전문 해석을 구현한 것으로 표시하지 않습니다.</p><p><a target="_blank" rel="noopener" href="https://github.com/yhj1024/manseryeok">계산 엔진 ↗</a> · <a target="_blank" rel="noopener" href="https://www.data.go.kr/data/15012679/openapi.do">한국천문연구원 API ↗</a> · <a href="vendor/manseryeok.LICENSE">MIT 라이선스</a></p>`);},
 async card(share=false){const p=state.path;if(!SidaeCore.endings[p])return;try{if(document.fonts)await document.fonts.load('24px "Sidae Korean"');const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const c=canvas.getContext('2d'),[title,color]=SidaeCore.endings[p],n=Object.keys(SidaeCore.endings).indexOf(p);c.fillStyle='#162c2a';c.fillRect(0,0,1080,1350);c.strokeStyle=color;c.lineWidth=3;c.strokeRect(50,50,980,1250);c.fillStyle=color;c.font='25px "Sidae Korean", sans-serif';c.fillText('時代因材 — 나의 또 다른 삶',90,130);c.font='24px "Sidae Korean", sans-serif';c.fillText('조선 · 1792년 · 각자장',90,195);const im=new Image();im.src='assets/cast-expressions.png';await im.decode();c.imageSmoothingEnabled=false;c.fillStyle=color;for(let x=0;x<7;x++)c.fillRect(90+x*130,260+((x+n)%3)*12,96,8);c.drawImage(im,0,0,256,384,100,290,320,480);if(!['AAA','AAB','BAA'].includes(p))c.drawImage(im,(p==='BAB'?2:0)*256,384,256,384,570,290,320,480);else{c.font='100px "Sidae Korean", serif';c.fillText(['刻','傳','準','共','影','手','立','續'][n],650,550);}const mascot=new Image();mascot.src=Kuong.sheet;await mascot.decode();const [mx,my,mw,mh]=Kuong.frames[Kuong.ending(p)];c.drawImage(mascot,mx,my,mw,mh,850,85,125,125*mh/mw);c.font='52px "Sidae Korean", serif';c.fillText(title,90,875);c.font='24px "Sidae Korean", sans-serif';let y=965;for(let i=0;i<3;i++){for(const l of wrap(c,`${i+1}. ${choiceAt(i,p).title}`,880)){c.fillText(l,90,y);y+=42;}}c.font='22px "Sidae Korean", sans-serif';c.fillText('시대와 환경이 달라지면, 나는 어떤 사람이 될까?',90,1200);c.font='18px "Sidae Korean", sans-serif';c.fillText('「마지막 도구」 · 창작 속 선택의 기록',90,1250);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();const file=new File([blob],'시대인재_'+title+'.png',{type:'image/png'});if(share&&navigator.canShare?.({files:[file]})){await navigator.share({title:'時代因材 · '+title,files:[file]});return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(share?'이 브라우저는 이미지 공유를 지원하지 않아 저장합니다.':'결과 카드를 저장했습니다.');}catch(e){if(e.name!=='AbortError')toast('이미지 저장을 완료하지 못했습니다. 다시 시도해 주세요.');}}
};
Sidae.load();
document.addEventListener('submit',e=>{if(e.target.id==='sd-form'){e.preventDefault();Sidae.submit(e.target);}});
document.addEventListener('change',e=>{const f=e.target.form;if(f?.id!=='sd-form')return;if(e.target.name==='calendar'){f.elements.leap.disabled=e.target.value!=='lunar';if(f.elements.leap.disabled)f.elements.leap.checked=false;}if(e.target.name==='unknown'){f.elements.time.disabled=e.target.checked;f.elements.time.required=!e.target.checked;}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-sd]');if(!b)return;e.stopPropagation();const a=b.dataset.sd;if(a==='card'||a==='share')Sidae.card(a==='share');else if(['form','analysis','method'].includes(a))Sidae[a]();});
